namespace sv_99423480cc074ee495d49c1eba6acf05.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

public record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public record StatusUpdate(string Status, string Location, DateTimeOffset Timestamp);

using sv_99423480cc074ee495d49c1eba6acf05.Client.Services;

namespace sv_99423480cc074ee495d49c1eba6acf05.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new ShipmentDetails(
            "TRK-001",
            "In Transit",
            "Chicago, IL",
            new DateTimeOffset(2026, 7, 14, 17, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate("Picked Up", "New York, NY", new DateTimeOffset(2026, 7, 8, 10, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Departed Facility", "New York, NY", new DateTimeOffset(2026, 7, 9, 6, 30, 0, TimeSpan.Zero)),
                new StatusUpdate("In Transit", "Chicago, IL", new DateTimeOffset(2026, 7, 10, 14, 0, 0, TimeSpan.Zero)),
            ]),
        ["TRK-002"] = new ShipmentDetails(
            "TRK-002",
            "Delivered",
            "San Francisco, CA",
            new DateTimeOffset(2026, 7, 10, 12, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate("Picked Up", "Seattle, WA", new DateTimeOffset(2026, 7, 7, 8, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("In Transit", "Portland, OR", new DateTimeOffset(2026, 7, 8, 11, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Out for Delivery", "San Francisco, CA", new DateTimeOffset(2026, 7, 10, 9, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 7, 10, 11, 45, 0, TimeSpan.Zero)),
            ]),
        ["TRK-003"] = new ShipmentDetails(
            "TRK-003",
            "Processing",
            "Dallas, TX",
            new DateTimeOffset(2026, 7, 16, 18, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate("Label Created", "Dallas, TX", new DateTimeOffset(2026, 7, 11, 7, 0, 0, TimeSpan.Zero)),
            ]),
    };

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_99423480cc074ee495d49c1eba6acf05.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p><em>Loading shipment details for @TrackingNumber&hellip;</em></p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger">
        <p>@_errorMessage</p>
        <button class="btn btn-primary" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <h2>Shipment @_shipment.TrackingNumber</h2>
    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>
        <dt>Location</dt>
        <dd>@_shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h3>Status History</h3>
    <table class="table">
        <thead>
            <tr>
                <th>Time</th>
                <th>Status</th>
                <th>Location</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in _shipment.Updates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Status</td>
                    <td>@update.Location</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any previous in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _errorMessage = null;
        _shipment = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed; do nothing
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

